def validate(
    self,
    value: Any,
    values: dict[str, Any] = {},
    *,
    loc: tuple[int | str, ...] = (),
) -> tuple[Any, list[dict[str, Any]]]:
    try:
        return (
            self._type_adapter.validate_python(value, from_attributes=True),
