class RepositoryTokenHashMixin[M]:
    token_hash_attribute: str

    def token_hash_clause(
        self: RepositoryTokenHashProtocol[M],
        candidates: dict[str | None, str],
        *,
        attribute: str | None = None,
    ) -> ColumnExpressionArgument[bool]:
        column: Mapped[str] = getattr(
            self.model, attribute or self.token_hash_attribute
        )
        return column.in_(candidates.values())

    async def rehash_token(
        self: RepositoryTokenHashProtocol[M],
        object: M,
        candidates: dict[str | None, str],
    ) -> M:
        current = candidates[get_current_secret_id()]
        if getattr(object, self.token_hash_attribute) == current:
            return object
        return await self.update(
            object, update_dict={self.token_hash_attribute: current}
        )

@classmethod
def __get_pydantic_json_schema__(
    cls, core_schema: CoreSchema, handler: GetJsonSchemaHandler
) -> JsonSchemaValue:
    schema = handler.resolve_ref_schema(handler(core_schema))
    pending: list[Any] = [schema]
    while pending:
        node = pending.pop()
        if isinstance(node, dict):
            if node.get("format") == "date-time":
                node.setdefault("examples", ["2026-01-01T00:00:00.000000Z"])
            for key, value in node.items():
                if key in {"properties", "patternProperties", "$defs"}:
                    pending.extend(value.values())
                elif key not in {"examples", "example", "default", "enum", "const"}:
                    pending.append(value)
        elif isinstance(node, list):
            pending.extend(node)
    return schema

@dataclasses.dataclass(slots=True)
class MergeJSONSchema:
    json_schema: JsonSchemaValue
    mode: Literal["validation", "serialization"] | None = None

    def __get_pydantic_json_schema__(
        self, core_schema: core_schema.CoreSchema, handler: GetJsonSchemaHandler
    ) -> JsonSchemaValue:
        mode = self.mode or handler.mode
        json_schema = handler(core_schema)
        if mode != handler.mode:
            return json_schema
        return {**json_schema, **self.json_schema}

    def __hash__(self) -> int:
        return hash(type(self.mode))

