def _get_by_sub_and_client_id(
    self,
    session: SyncSession,
    *,
    sub_type: SubType,
    sub_id: uuid.UUID,
    client_id: str,
) -> OAuth2Grant | None:
    statement = select(OAuth2Grant).where(OAuth2Grant.client_id == client_id)
    if sub_type == SubType.user:
        statement = statement.where(OAuth2Grant.user_id == sub_id)
    elif sub_type == SubType.organization:
        statement = statement.where(OAuth2Grant.organization_id == sub_id)
    else:
        raise NotImplementedError()
    result = session.execute(statement)
    return result.unique().scalar_one_or_none()

class ExternalEventsUnhandledInvariant(Invariant):
    LEEWAY = timedelta(minutes=10)
    LIMIT = 10

    async def check(self) -> None:
        repository = ExternalEventRepository.from_session(self.session)
        external_events, count = await repository.get_unhandled_ids(
            utc_now() - self.LEEWAY, limit=self.LIMIT
        )
        if count > 0:
            raise ExternalEventsUnhandledInvariantError(count, external_events)

class PayoutTransactionsAmountInvariantError(InvariantError):
    """Exception raised when the PayoutTransactionsAmountInvariant check fails."""

    def __init__(
        self, count: int, payout_transactions: list[uuid.UUID], differences: list[int]
    ) -> None:
        message = (
            f"Found {count} payout transactions with amount mismatch "
            "between payout and sum of paid transactions."
        )
        super().__init__(
            PayoutTransactionsAmountInvariant,
            message,
            {
                "count": count,
                "payout_transactions": {
                    "ids": payout_transactions,
                    "differences": differences,
                    "has_more": count > len(payout_transactions),
                },
            },
        )

