def type_alias_type_ref(type_: TypeAliasType) -> str:
    """Produce a reference for a type alias."""
    origin: TypeAliasType = get_origin(type_) or type_

    module_name = type_.__module__
    if module_name is None:
        module_name = '<No __module__>'

    if sys.version_info >= (3, 15):
        type_ref = f'{module_name}.{origin.__qualname__}:{id(origin)}'
    else:
        type_ref = f'{module_name}.{origin.__name__}:{id(origin)}'

    return f'{type_ref}{_args_ref(get_args(type_))}'

def signature_no_eval(f: Callable[..., Any]) -> Signature:
    """Get the signature of a callable without evaluating any annotations."""
    if sys.version_info >= (3, 14):
        from annotationlib import Format

        return signature(f, annotation_format=Format.FORWARDREF)
    else:
        return signature(f)

def unique_list(
    input_list: list[T] | tuple[T, ...],
    *,
    name_factory: Callable[[T], str] = str,
) -> list[T]:
    """Make a list unique while maintaining order."""
    result: list[T] = []
    result_names: list[str] = []
    for v in input_list:
        v_name = name_factory(v)
        if v_name not in result_names:
            result_names.append(v_name)
            result.append(v)
        else:
            result[result_names.index(v_name)] = v

    return result

def all_identical(left: Iterable[Any], right: Iterable[Any]) -> bool:
    """Check that the items of `left` are the same objects as those in `right`."""
    for left_item, right_item in zip_longest(left, right, fillvalue=_SENTINEL):
        if left_item is not right_item:
            return False
    return True

